def choose_best(candidates):
    winner = max(candidates, key=lambda c: c['score'])
    return {
        'selected_id': winner['id'],
        'selected_index': candidates.index(winner)
    }

def snapshot(candidates):
    # Snapshot encodes identity differently
    return [
        {
            'snapshot_id': i,
            'origin_ref': f"user::{c['id']}",
            'score': c['score'],
            'penalty': c['penalty']
        }
        for i, c in enumerate(candidates)
    ]

def normalize(candidates):
    finalized = [
        {
            'origin_ref': c['origin_ref'],
            'final_score': c['score'] - c['penalty']
        }
        for c in candidates
    ]
    return sorted(finalized, key=lambda c: -c['final_score'])

def commit(candidates, selection):
    # BUG: uses stale index and ignores representation change
    return candidates[selection['selected_index']]

